definitions:
open SimpleGraph in
def IsProperC {V : Type} (G : SimpleGraph V) {C : Type} (f : V → C) : Prop :=
  ∀ a b : V, G.Adj a b → f a ≠ f b

open SimpleGraph in
def IsCUB {V : Type} (G : SimpleGraph V) : Prop :=
  ∃ H : ℕ → SimpleGraph V, (∀ i, ∃ f : V → Bool, IsProperC (H i) f) ∧ G = ⨆ i, H i
